-- Additive expansion: rights, collaboration, discovery, funding and revenue are separate routes.
CREATE TABLE pathway_catalog (key text PRIMARY KEY, spec jsonb NOT NULL);
ALTER TABLE pathway_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_read ON pathway_catalog FOR SELECT TO authenticated USING (true);
GRANT SELECT ON pathway_catalog TO authenticated;
INSERT INTO pathway_catalog(key,spec) VALUES ('federal_license', $catalog${"key": "federal_license", "name": "License a federal invention", "category": "IP rights", "money": "Usually you pay fees or royalties to the licensor. The lab does not normally pay you.", "summary": "Secure exclusive, partially exclusive or nonexclusive rights to a federal invention.", "boundary": "A license is permission to use IP, not an R&D award. Verify ownership, availability, field of use and manufacturing obligations with the licensor.", "area": "licensing", "checks": ["Who owns the invention, and what patent rights are currently available?", "What field, territory, exclusivity and U.S. manufacturing obligations apply?", "What fees, royalties, diligence milestones and evidence of capability will the lab require?"], "steps": [{"title": "Confirm ownership and the licensing contact", "description": "Find the official listing, patent identifiers and authorized licensing office. Record sources; a listing alone is not a license."}, {"title": "Define the rights you need", "description": "Compare evaluation, option, nonexclusive and exclusive rights, including field and geography."}, {"title": "Prepare a development and marketing plan", "description": "Describe customer problem, evidence, development milestones, resources, commercialization timeline and risks. 35 USC 209 requires a development or marketing plan for a federal patent license."}, {"title": "Build a licensing cost and obligations model", "description": "Keep upfront fees, patent costs, minimum royalties, running royalties and reporting obligations separate from award income. Do not invent terms."}, {"title": "Review the application and negotiate with the licensor", "description": "Obtain the office\u2019s actual forms and seek legal review; draft correspondence remains unsent."}, {"title": "Track execution and ongoing compliance", "description": "Only record execution after human confirmation. Track diligence, reporting, payments and any manufacturing commitments."}], "sections": ["Commercialization summary", "Technology and requested rights", "Customer problem and evidence", "Development milestones and resources", "Go-to-market and manufacturing plan", "Financial assumptions and royalty scenarios", "Risks, diligence and open terms"], "sources": [{"label": "Federal licensing requirements, 35 USC 209", "url": "https://www.law.cornell.edu/uscode/text/35/209"}], "inquiry": "Could you confirm the current availability of these rights, the licensing process, and your required commercialization-plan format?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('university_license', $catalog${"key": "university_license", "name": "University / Bayh-Dole license", "category": "IP rights", "money": "You pay the institution under negotiated terms, often royalties, fees or equity. This is not an SBIR-style award.", "summary": "Commercialize university-owned IP, including inventions arising from federally funded research.", "boundary": "Federal funding does not mean the government owns the patent. Confirm chain of title and the institution\u2019s authority; retained government rights and other obligations may apply.", "area": "licensing", "checks": ["Has the institution confirmed ownership, inventorship and its authority to license?", "Is this a federally funded subject invention, and which government or sponsor rights remain?", "What license scope, diligence, patent reimbursement, royalty, equity and manufacturing terms apply?"], "steps": [{"title": "Find the institution\u2019s technology-transfer office", "description": "Verify the official university listing and authorized contact, not only a lab or researcher."}, {"title": "Check title, funding and encumbrances", "description": "Ask about assignments, federal funding, sponsor rights, co-owners and prior licenses."}, {"title": "Prepare the commercialization case", "description": "Build market evidence, development plan, team capability and requested rights."}, {"title": "Model institutional license economics", "description": "Separate royalties, equity, patent expenses, milestone payments and minimums from cash available to the company."}, {"title": "Review option and license documents", "description": "Ask counsel to review scope, diligence, retained rights, U.S. manufacturing, publication and improvements."}, {"title": "Track license performance", "description": "Record execution only on confirmation; track reporting, payments and diligence obligations."}], "sections": ["Invention and chain-of-title questions", "Requested license scope", "Commercialization and development plan", "Team and resources", "Economics and diligence", "Government and sponsor rights", "Unresolved legal terms"], "sources": [{"label": "NIST Bayh-Dole framework", "url": "https://www.nist.gov/tpo/policy-coordination/bayh-dole-act"}, {"label": "NIST ownership and reporting FAQs", "url": "https://www.nist.gov/tpo/policy-coordination/bayh-dole-act/2018-faqs"}], "inquiry": "Could your technology-transfer office confirm ownership, funding-related obligations, available rights and your startup licensing process?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('crada', $catalog${"key": "crada", "name": "CRADA collaboration", "category": "Collaboration", "money": "The lab can contribute people, facilities, equipment and IP, but not funds to the non-federal partner under 15 USC 3710a.", "summary": "Work jointly with a federal lab on a mission-aligned research effort.", "boundary": "A CRADA is not a procurement contract or a financial-assistance cooperative agreement. Budget the company\u2019s own costs and any payments to the lab separately.", "area": "licensing", "checks": ["Does the proposed work align with the lab\u2019s mission and available resources?", "Who supplies each resource and pays each cost, without lab funds flowing to the non-federal partner under the CRADA?", "How will background IP, new inventions, licensing options, publication and protected data be handled?"], "steps": [{"title": "Identify a lab collaborator and mission fit", "description": "Verify the official partnership office and relevant technical group."}, {"title": "Write a joint statement of work", "description": "Separate lab and company work packages, milestones, people, facilities and deliverables."}, {"title": "Map contributions and funding sources", "description": "List cash and in-kind resources by party. Do not show the CRADA as a cash award to the company."}, {"title": "Map IP, data and publication terms", "description": "Distinguish pre-existing rights from new inventions and any option to negotiate a license."}, {"title": "Prepare the collaboration package for review", "description": "Include work plan, contributions, background IP and questions; obtain the lab\u2019s process and legal review."}, {"title": "Track the agreement and research milestones", "description": "No work or execution is presumed. Record agreed terms and milestones only after confirmation."}], "sections": ["Joint research objective", "Lab and company work packages", "Contributions and responsibility matrix", "Background IP and new invention treatment", "Data, publication and confidentiality", "Milestones and governance", "Unresolved terms and approvals"], "sources": [{"label": "CRADA authority and no-funds rule, 15 USC 3710a", "url": "https://www.law.cornell.edu/uscode/text/15/3710a"}], "inquiry": "Would this joint research objective fit a CRADA at your lab? Please advise on mission fit, contributions, background IP and your review process.", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('icorps', $catalog${"key": "icorps", "name": "I-Corps customer discovery", "category": "Customer discovery", "money": "Training support and permitted participation/customer-discovery expenses, subject to the program. Not general R&D funding.", "summary": "Test the market through structured interviews, mentoring and commercialization training.", "boundary": "Not a substitute for SBIR or other R&D funding. NSF institutional routes and NIH award-dependent offerings have different eligibility; check the current call.", "area": "validation", "checks": ["Which NSF regional/national or NIH offering is currently open and appropriate for this team?", "What institutional, prior-award, team and participation requirements apply?", "Which customer-discovery costs are allowed, and what work or expenses are excluded?"], "steps": [{"title": "Choose and verify the current I-Corps route", "description": "Check NSF national/regional eligibility or the current NIH offering; do not assume a prior award makes the team eligible."}, {"title": "Assemble the required team", "description": "Confirm entrepreneurial and technical leads, mentor and institutional submission responsibility for the chosen route."}, {"title": "Draft the problem and customer hypotheses", "description": "Keep hypotheses distinct from completed interviews and evidence."}, {"title": "Prepare interview and learning plans", "description": "Define segments, recruitment, interview questions and a learning log; never invent interview results."}, {"title": "Prepare a restricted participation budget", "description": "Use the current offering\u2019s permitted expenses and requirements, not a general R&D budget."}, {"title": "Track training and validated learning", "description": "Record real attendance and interviews, update assumptions and decide whether to pursue, pivot or stop."}], "sections": ["Team and eligibility", "Technology and customer hypotheses", "Discovery goals and interview segments", "Interview guide and outreach drafts", "Participation plan and restricted budget", "Learning log and decision gates"], "sources": [{"label": "NSF National I-Corps Teams", "url": "https://www.nsf.gov/funding/initiatives/i-corps/national-teams-applicants"}, {"label": "NIH SEED programs", "url": "https://seed.nih.gov/"}], "inquiry": "Could you confirm the current customer-discovery offering, eligibility route, team requirements and application process for this technology?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('sbir_sttr', $catalog${"key": "sbir_sttr", "name": "SBIR / STTR R&D", "category": "Funding", "money": "Competitive R&D award under the selected agency\u2019s grant or contract terms. Not guaranteed, and later phases are not automatic.", "summary": "Pursue small-business research funding when an actual solicitation and the company\u2019s eligibility fit.", "boundary": "SBIR and STTR have distinct rules. STTR requires a qualifying research-institution partnership; confirm work share and IP allocation against current rules.", "area": "funding", "checks": ["Does the company meet the current ownership, size, location and PI requirements?", "Does the exact solicitation fit the technical work and, for STTR, the partner/work-share rules?", "What rights, registrations, documents, budget rules and official deadlines apply?"], "steps": [{"title": "Find an official current solicitation", "description": "Search and save the exact topic, status, agency and source. An old announcement is not an open opportunity."}, {"title": "Resolve company, PI and partner eligibility", "description": "Capture evidence and unanswered questions rather than marking eligibility by inference."}, {"title": "Check IP access and research scope", "description": "Separate a license application from award eligibility and confirm what rights are needed when."}, {"title": "Prepare the technical and commercialization package", "description": "Use the actual solicitation\u2019s required sections, page limits and evaluation criteria."}, {"title": "Validate budget, registrations and deadline", "description": "Keep alternatives separate. Confirm official deadline time, time zone and amendments."}, {"title": "Review, submit externally and track outcomes", "description": "Human submission and confirmation only; record post-award obligations if an award actually occurs."}], "sections": ["Technical problem and innovation", "Research objectives and methods", "Commercialization evidence", "Team and facilities", "Partner and IP arrangements", "Budget and justification", "Eligibility, registrations and required attachments"], "sources": [{"label": "SBA SBIR/STTR", "url": "https://www.sbir.gov/"}, {"label": "Official opportunity search", "url": "https://www.grants.gov/search-grants"}], "inquiry": "Could you clarify the topic fit, submission requirements and unresolved eligibility questions for this solicitation?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('federal_assistance', $catalog${"key": "federal_assistance", "name": "Grants & cooperative agreements", "category": "Funding", "money": "Financial assistance for an authorized public purpose; allowable costs, cost sharing and payments depend on the award.", "summary": "Find non-SBIR agency grants and financial-assistance cooperative agreements.", "boundary": "A financial-assistance cooperative agreement is not a CRADA. Substantial agency involvement distinguishes it from a grant; many calls do not admit for-profit startups.", "area": "funding", "checks": ["Does the opportunity explicitly allow this applicant type and proposed work?", "Is the instrument a grant or financial-assistance cooperative agreement, and what agency involvement is expected?", "What cost share, allowable costs, registrations, IP/data terms and reporting obligations apply?"], "steps": [{"title": "Search official assistance opportunities", "description": "Search Grants.gov and the agency portal; review the actual notice and amendments."}, {"title": "Check applicant and project eligibility", "description": "Do not equate a keyword match with eligibility. Record restrictions on organizations and geography."}, {"title": "Map notice requirements and evaluation criteria", "description": "Build a compliance matrix tied to the current official notice."}, {"title": "Draft the work plan and outcomes", "description": "Include measurable objectives, evaluation, partners and any substantial agency involvement."}, {"title": "Prepare the budget and cost-share evidence", "description": "Verify allowable costs, reimbursement/advance terms and realistic cash flow."}, {"title": "Review the application and post-award duties", "description": "A human submits; track financial/performance reporting, IP obligations and award conditions only when confirmed."}], "sections": ["Public-purpose alignment and eligibility", "Work plan and measurable outcomes", "Team and partners", "Budget, cost share and justification", "Agency involvement and reporting", "IP, data and compliance", "Notice-specific attachments"], "sources": [{"label": "Grants.gov opportunity search", "url": "https://www.grants.gov/search-grants"}, {"label": "Cooperative agreements, 31 USC 6305", "url": "https://www.law.cornell.edu/uscode/text/31/6305"}], "inquiry": "Could you clarify applicant eligibility, the funding instrument, cost-share requirements and the application process under this notice?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('federal_contract', $catalog${"key": "federal_contract", "name": "Federal contracts & BAA calls", "category": "Revenue", "money": "Payment for contracted work or deliverables under the awarded contract. Bidding is not payment.", "summary": "Sell R&D, prototypes, services or products to a federal buyer, directly or through a prime contractor.", "boundary": "A BAA is a solicitation approach, not a universal award type. Read the call to determine the actual instrument and agency-specific rules.", "area": "funding", "checks": ["Is there a real agency requirement, funded call or prime-contractor need that fits?", "What instrument, competition route, registrations, certifications and security rules apply?", "Which deliverables, acceptance criteria, IP/data rights, payment and compliance terms will govern?"], "steps": [{"title": "Find an official requirement or BAA", "description": "Use SAM.gov or the agency\u2019s contracting/R&D portal. Verify that the notice is current and relevant."}, {"title": "Qualify the buying route and requirements", "description": "Distinguish market research/RFIs, solicitations and awards; evaluate prime or subcontract routes."}, {"title": "Build a compliance and data-rights matrix", "description": "Map instructions, clauses, deliverables, security/export controls and technical-data markings."}, {"title": "Draft the technical approach and performance plan", "description": "Connect measurable work packages to the buyer\u2019s stated requirement, not only the technology."}, {"title": "Prepare price/cost and delivery assumptions", "description": "Model acceptance, invoicing and cash flow; do not imply a bid or BAA guarantees funds."}, {"title": "Review and track the contract lifecycle", "description": "Human offer/submission and signature only. Track actual award, deliverables, invoices and changes separately."}], "sections": ["Requirement and instrument", "Technical approach", "Statement of work and deliverables", "Schedule and acceptance criteria", "Price/cost and payment assumptions", "IP/data rights and compliance", "Required representations and attachments"], "sources": [{"label": "FAR BAA guidance", "url": "https://www.acquisition.gov/far/35.016"}, {"label": "Federal contract opportunities", "url": "https://sam.gov/opportunities"}], "inquiry": "Could you clarify the requirement, award instrument, submission route, deliverables and data-rights expectations for this opportunity?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('other_transaction', $catalog${"key": "other_transaction", "name": "Other transactions (OTs)", "category": "Funding", "money": "Negotiated research or prototype funding under an agency\u2019s authority and agreement. Cost sharing may apply.", "summary": "Explore eligible nontraditional research/prototype routes, including agency and consortium calls.", "boundary": "Not a standard FAR procurement or grant. Eligibility, contributions, IP and follow-on production conditions are agreement-specific; follow-on work is not automatic.", "area": "funding", "checks": ["Which agency authority and current research/prototype call applies?", "Does the team satisfy applicable participation or cost-sharing conditions?", "What IP/data rights, payment milestones and follow-on production conditions are negotiated?"], "steps": [{"title": "Verify the agency authority and official call", "description": "Do not assume all agencies or consortia operate under identical rules."}, {"title": "Check participation and consortium conditions", "description": "Document nontraditional participation, membership costs, eligibility and any cost-share requirements."}, {"title": "Draft a prototype or research plan", "description": "Identify the mission need, testable objectives, work packages and measurable milestones."}, {"title": "Model contributions, milestone payments and IP", "description": "Distinguish negotiated terms from assumptions and confirm data-rights protections."}, {"title": "Review the agreement and transition approach", "description": "Seek legal review; identify any conditions for follow-on production without presuming an entitlement."}, {"title": "Track authorized work and milestone acceptance", "description": "Record agreement execution, funded milestones and any follow-on award only with human confirmation."}], "sections": ["Mission fit and authority", "Eligibility and team roles", "Prototype/research plan", "Milestones and acceptance", "Contributions and payment terms", "IP/data rights", "Transition assumptions and open terms"], "sources": [{"label": "DoD OT policy and current guides", "url": "https://www.acq.osd.mil/asda/dpc/cp/policy/other-policy-areas.html"}], "inquiry": "Could you confirm the applicable authority, participation conditions, milestone structure and IP/data-rights process for this OT opportunity?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('prize', $catalog${"key": "prize", "name": "Prizes & challenge competitions", "category": "Funding", "money": "Prize money only if the stated rules and selection criteria are met. Usually not reimbursement for all development effort.", "summary": "Compete against a defined challenge or performance target.", "boundary": "Prize terms, eligibility, IP rights, testing, judging and payment differ by challenge. Entry is not an award or a paid contract.", "area": "funding", "checks": ["Is the competition open, and is this team eligible under the current rules?", "What technical threshold, judging process, submissions and official deadlines apply?", "What are the prize-payment, IP, data, publicity and participation-cost terms?"], "steps": [{"title": "Find and verify the official challenge rules", "description": "Read amendments and distinguish current challenges from past winners."}, {"title": "Check eligibility and ownership requirements", "description": "Confirm who can enter and which IP/data/publicity rights are retained or granted."}, {"title": "Translate judging criteria into tests", "description": "Create measurable acceptance targets and a test/evidence plan."}, {"title": "Budget the effort without assuming a win", "description": "Estimate team-funded costs and treat prize income as contingent."}, {"title": "Prepare the demonstration and submission", "description": "Compile evidence, reproducibility details and required materials for human review."}, {"title": "Track results and commercial follow-through", "description": "Only record a win/payment after confirmation; develop customer opportunities independently."}], "sections": ["Eligibility and rules matrix", "Proposed solution", "Performance targets and test plan", "Demonstration evidence", "Entry costs and contingent prize", "IP/data conditions and required materials"], "sources": [{"label": "NASA Centennial Challenges", "url": "https://www.nasa.gov/prizes-challenges-and-crowdsourcing/centennial-challenges/"}], "inquiry": "Could you clarify eligibility, judging evidence, IP conditions and the submission process for this challenge?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('facility_access', $catalog${"key": "facility_access", "name": "Lab facilities & sponsored work", "category": "Collaboration", "money": "You may pay for lab work or proprietary access. Some nonproprietary access is allocated without facility charges; it is not cash paid to you.", "summary": "Use unique equipment, testing or expertise through user agreements, sponsored research or DOE Strategic Partnership Projects.", "boundary": "Terms vary by lab. Publication, proprietary use, cost recovery, liability and IP differ; access does not itself grant a commercial patent license.", "area": "licensing", "checks": ["Which user-facility, sponsored-work or SPP agreement fits the planned work?", "Are results proprietary or publishable, and what access charges and IP/data terms apply?", "What proposal, scheduling, safety, export-control and payment requirements must be met?"], "steps": [{"title": "Find a suitable facility and access route", "description": "Verify capabilities with the facility; do not assume available capacity."}, {"title": "Choose proprietary or nonproprietary treatment", "description": "Clarify publication and data protection before sharing sensitive information."}, {"title": "Write the experiment or sponsored-work scope", "description": "Define sample needs, measurements, deliverables and team responsibilities."}, {"title": "Confirm costs, scheduling and IP terms", "description": "Ask for actual access terms or quotation; separate lab payments from business funding."}, {"title": "Prepare access and safety documentation", "description": "Use the facility\u2019s current proposal, user agreement and training requirements."}, {"title": "Track access, results and downstream rights", "description": "Retain original measurements separately from AI summaries and check any additional commercialization license needed."}], "sections": ["Research/test objective", "Facility capability and access route", "Experimental or sponsored-work plan", "Proprietary treatment and publication", "Cost, schedule and responsibilities", "Safety and IP/data questions"], "sources": [{"label": "DOE laboratory partnering guide", "url": "https://www.energy.gov/sites/default/files/2024-12/TTWG_Partnering_Guide.pdf"}], "inquiry": "Could you advise on the correct facility or sponsored-work agreement, availability, costs, proprietary treatment and required access documents?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('private_capital', $catalog${"key": "private_capital", "name": "Private capital & financing", "category": "Funding", "money": "Investors provide capital for negotiated ownership/rights; loans require repayment. Neither is government revenue.", "summary": "Combine founder capital, investors, strategic partners or debt with commercialization milestones.", "boundary": "Not a federal award. Dilution, repayment, covenants, securities law and licensing restrictions require professional review.", "area": "funding", "checks": ["What milestone and runway need does the financing cover?", "What dilution, repayment, governance and license restrictions can the company accept?", "Which traction, ownership, diligence and financial assumptions are evidenced versus unproven?"], "steps": [{"title": "Define the milestone and financing need", "description": "Separate development budget, operating runway and royalty obligations."}, {"title": "Choose financing routes to investigate", "description": "Compare investor capital, strategic funding, founder resources and debt without assuming availability."}, {"title": "Prepare the evidence and diligence package", "description": "Collect IP access, cap table, customer evidence, technical risks and financial assumptions."}, {"title": "Build financing and runway scenarios", "description": "Separate committed cash from possible awards and investment; include downside cases."}, {"title": "Draft investor/lender materials for review", "description": "Use evidence-qualified claims and obtain appropriate financial/legal advice."}, {"title": "Track discussions and actual commitments", "description": "Only record committed financing and received funds from confirmed documents, never from interest alone."}], "sections": ["Milestone and use of funds", "Customer and technical evidence", "IP access and ownership", "Runway and financing scenarios", "Team and diligence checklist", "Unresolved financial/legal terms"], "sources": [{"label": "SBA funding guidance", "url": "https://www.sba.gov/business-guide/plan-your-business/fund-your-business"}], "inquiry": "Would this commercialization milestone fit your investment or financing criteria, and what diligence materials would you need to evaluate it?", "checked_on": "2026-10-11"}$catalog$::jsonb);
INSERT INTO pathway_catalog(key,spec) VALUES ('paid_pilot', $catalog${"key": "paid_pilot", "name": "Paid pilots & commercial sales", "category": "Revenue", "money": "Customers pay for agreed deliverables, products or services. Interest, interviews and unsigned letters are not revenue.", "summary": "Validate a buying decision through paid evaluation, pilots, development partnerships or commercial sales.", "boundary": "A pilot is not automatically paid. Verify IP permissions, promised performance, regulatory claims, procurement terms and acceptance before committing.", "area": "commercialization", "checks": ["Who is the buyer and budget owner, and is payment actually authorized?", "Does the company have rights and capacity to deliver the proposed pilot or product?", "What price, success criteria, acceptance, liability, data and conversion terms will be agreed?"], "steps": [{"title": "Qualify the buyer and purchasing process", "description": "Distinguish users, champions, decision-makers and the actual budget owner."}, {"title": "Define a narrow, measurable paid pilot", "description": "Agree a problem, scope, baseline, success criteria and credible performance claims."}, {"title": "Check IP permissions and delivery risks", "description": "A research license may not allow commercial sales; confirm permitted activities and regulatory requirements."}, {"title": "Prepare scope, price and acceptance terms", "description": "Separate quoted, contracted, invoiced and received amounts; seek legal review of customer terms."}, {"title": "Draft the customer proposal and rollout plan", "description": "Keep evidence and assumptions visible; no commitments or email are sent automatically."}, {"title": "Track delivery, payment and conversion", "description": "Record real acceptance and receipts, then evaluate repeat sales or a production contract."}], "sections": ["Buyer problem and qualification", "Pilot scope and success criteria", "Delivery and support plan", "Price and payment milestones", "IP, data, regulatory and liability questions", "Acceptance and commercial conversion"], "sources": [{"label": "SBA business planning guidance", "url": "https://www.sba.gov/business-guide/plan-your-business/fund-your-business"}], "inquiry": "Would a narrowly scoped paid pilot be useful? We would like to discuss the problem, budget owner, measurable success criteria, procurement process and payment terms.", "checked_on": "2026-10-11"}$catalog$::jsonb);

CREATE TABLE project_pathways (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL DEFAULT auth.user_id(),
 project_id uuid NOT NULL, pathway_key text NOT NULL,
 status text NOT NULL DEFAULT 'preparing' CHECK(status IN ('considering','preparing','active','paused','closed')),
 notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(project_id,pathway_key)
);
ALTER TABLE project_pathways ADD CONSTRAINT project_pathways_project_fk FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE project_pathways ADD CONSTRAINT project_pathways_catalog_fk FOREIGN KEY(pathway_key) REFERENCES pathway_catalog(key);
ALTER TABLE project_pathways ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_select ON project_pathways FOR SELECT TO authenticated USING(user_id=auth.user_id());
CREATE POLICY own_insert ON project_pathways FOR INSERT TO authenticated WITH CHECK(user_id=auth.user_id() AND EXISTS(SELECT 1 FROM projects p WHERE p.id=project_id AND p.user_id=auth.user_id()));
CREATE POLICY own_update ON project_pathways FOR UPDATE TO authenticated USING(user_id=auth.user_id()) WITH CHECK(user_id=auth.user_id() AND EXISTS(SELECT 1 FROM projects p WHERE p.id=project_id AND p.user_id=auth.user_id()));
CREATE POLICY own_delete ON project_pathways FOR DELETE TO authenticated USING(user_id=auth.user_id());
GRANT SELECT,INSERT,UPDATE,DELETE ON project_pathways TO authenticated;
CREATE TABLE workflow_runs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL DEFAULT auth.user_id(),
 project_id uuid NOT NULL, pathway_id uuid NOT NULL, request_key uuid NOT NULL DEFAULT gen_random_uuid(),
 action text NOT NULL CHECK(action IN ('research','draft','review')),
 status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','done','failed','canceled')),
 session_id text, error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(user_id,request_key)
);
ALTER TABLE workflow_runs ADD CONSTRAINT workflow_runs_project_fk FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE workflow_runs ADD CONSTRAINT workflow_runs_pathway_fk FOREIGN KEY(pathway_id) REFERENCES project_pathways(id) ON DELETE CASCADE;
CREATE UNIQUE INDEX workflow_one_active ON workflow_runs(pathway_id,action) WHERE status='running';
ALTER TABLE workflow_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_select ON workflow_runs FOR SELECT TO authenticated USING(user_id=auth.user_id());
CREATE POLICY own_insert ON workflow_runs FOR INSERT TO authenticated WITH CHECK(user_id=auth.user_id() AND EXISTS(SELECT 1 FROM project_pathways p WHERE p.id=pathway_id AND p.project_id=workflow_runs.project_id AND p.user_id=auth.user_id()));
CREATE POLICY own_update ON workflow_runs FOR UPDATE TO authenticated USING(user_id=auth.user_id()) WITH CHECK(user_id=auth.user_id() AND EXISTS(SELECT 1 FROM project_pathways p WHERE p.id=pathway_id AND p.project_id=workflow_runs.project_id AND p.user_id=auth.user_id()));
CREATE POLICY own_delete ON workflow_runs FOR DELETE TO authenticated USING(user_id=auth.user_id());
GRANT SELECT,INSERT,UPDATE,DELETE ON workflow_runs TO authenticated;
ALTER TABLE tasks ADD COLUMN pathway_id uuid;
ALTER TABLE questions ADD COLUMN pathway_id uuid;
ALTER TABLE communications ADD COLUMN pathway_id uuid;
ALTER TABLE documents ADD COLUMN pathway_id uuid;
ALTER TABLE documents ADD COLUMN workflow_run_id uuid UNIQUE;
ALTER TABLE documents ADD CONSTRAINT documents_workflow_run_fk FOREIGN KEY(workflow_run_id) REFERENCES workflow_runs(id) ON DELETE SET NULL;
ALTER TABLE tasks ADD CONSTRAINT tasks_pathway_fk FOREIGN KEY(pathway_id) REFERENCES project_pathways(id) ON DELETE SET NULL;
ALTER TABLE questions ADD CONSTRAINT questions_pathway_fk FOREIGN KEY(pathway_id) REFERENCES project_pathways(id) ON DELETE SET NULL;
ALTER TABLE communications ADD CONSTRAINT communications_pathway_fk FOREIGN KEY(pathway_id) REFERENCES project_pathways(id) ON DELETE SET NULL;
ALTER TABLE documents ADD CONSTRAINT documents_pathway_fk FOREIGN KEY(pathway_id) REFERENCES project_pathways(id) ON DELETE SET NULL;
CREATE FUNCTION check_pathway_parent() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
BEGIN
 IF NEW.pathway_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM project_pathways WHERE id=NEW.pathway_id AND project_id=NEW.project_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Pathway must belong to this project and account'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER pathway_parent_check BEFORE INSERT OR UPDATE ON tasks FOR EACH ROW EXECUTE FUNCTION check_pathway_parent();
CREATE TRIGGER pathway_parent_check BEFORE INSERT OR UPDATE ON questions FOR EACH ROW EXECUTE FUNCTION check_pathway_parent();
CREATE TRIGGER pathway_parent_check BEFORE INSERT OR UPDATE ON communications FOR EACH ROW EXECUTE FUNCTION check_pathway_parent();
CREATE TRIGGER pathway_parent_check BEFORE INSERT OR UPDATE ON documents FOR EACH ROW EXECUTE FUNCTION check_pathway_parent();
CREATE FUNCTION check_workflow_document() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
BEGIN
 IF NEW.workflow_run_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workflow_runs WHERE id=NEW.workflow_run_id AND project_id=NEW.project_id AND pathway_id=NEW.pathway_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Workflow result must belong to this project, pathway and account'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER workflow_document_check BEFORE INSERT OR UPDATE ON documents FOR EACH ROW EXECUTE FUNCTION check_workflow_document();
ALTER TABLE technologies ADD COLUMN origin_kind text NOT NULL DEFAULT 'unknown' CHECK(origin_kind IN ('unknown','federal_lab','university','other'));
ALTER TABLE technologies ADD COLUMN funding_relevance text NOT NULL DEFAULT '';
UPDATE technologies SET funding_relevance=sbir_relevance;
ALTER TABLE opportunities DROP CONSTRAINT opportunities_program_check;
ALTER TABLE opportunities ADD CONSTRAINT opportunities_program_check CHECK(program IN ('SBIR','STTR','SBIR/STTR','Other','Grant','Cooperative agreement','Contract','Other transaction','Prize','I-Corps','Private capital','Paid pilot'));
ALTER TABLE opportunities ALTER COLUMN program SET DEFAULT 'Other';
ALTER TABLE opportunities ADD COLUMN external_provider text NOT NULL DEFAULT '';
ALTER TABLE opportunities ADD COLUMN external_id text NOT NULL DEFAULT '';
CREATE UNIQUE INDEX opportunities_external_unique ON opportunities(user_id,external_provider,external_id) WHERE external_id<>'';

-- The entire plan is created once, transactionally, with caller RLS. No user edits are overwritten on repeat.
CREATE FUNCTION create_pathway_plan(target_project uuid, selected_pathway text) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE uid text:=public.app_user_id(); p projects%ROWTYPE; spec jsonb; path_id uuid; item jsonb; prev uuid; task_id uuid; packet text; sample_prefix text:=''; src text:='';
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
 SELECT * INTO p FROM projects WHERE id=target_project AND user_id=uid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
 SELECT c.spec INTO spec FROM pathway_catalog c WHERE key=selected_pathway;
 IF spec IS NULL THEN RAISE EXCEPTION 'Unknown pathway'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(target_project::text||selected_pathway,0));
 SELECT id INTO path_id FROM project_pathways WHERE project_id=target_project AND pathway_key=selected_pathway;
 IF path_id IS NOT NULL THEN RETURN jsonb_build_object('id',path_id,'created',false); END IF;
 INSERT INTO project_pathways(project_id,pathway_key) VALUES(target_project,selected_pathway) RETURNING id INTO path_id;
 IF EXISTS(SELECT 1 FROM technologies WHERE id=p.technology_id AND is_sample) THEN sample_prefix:='[SAMPLE] '; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(spec->'steps') LOOP
   INSERT INTO tasks(project_id,pathway_id,title,description,area,priority,created_by,depends_on)
   VALUES(target_project,path_id,sample_prefix||(item->>'title'),item->>'description',spec->>'area',2,'template',prev) RETURNING id INTO task_id;
   prev:=task_id;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(spec->'checks') LOOP
   INSERT INTO questions(project_id,pathway_id,kind,area,text,blocking) VALUES(target_project,path_id,'question',spec->>'area',sample_prefix||(item#>>'{}'),true);
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(spec->'sources') LOOP
   src:=src||E'
- '||(item->>'label')||': '||(item->>'url');
 END LOOP;
 packet:='# '||sample_prefix||(spec->>'name')||E' working plan

Planning template, not verified evidence, an executed agreement or an award. Nothing has been sent or submitted. General information, not legal advice.

';
 IF sample_prefix<>'' THEN packet:=packet||E'Fictional demonstration. Do not submit or contact real counterparties using these facts.

'; END IF;
 packet:=packet||'## Money flow'||E'
'||(spec->>'money')||E'

'||(spec->>'boundary')||E'

## Recorded project context (not independently verified)
'||p.name||E'
Problem: '||p.problem||E'
Customer: '||p.target_customer||E'
Working thesis: '||p.business_thesis||E'
';
 FOR item IN SELECT value FROM jsonb_array_elements(spec->'sections') LOOP
   packet:=packet||E'
## '||(item#>>'{}')||E'
To prepare. Add sourced facts, separate estimates and hypotheses, and identify unanswered questions.
';
 END LOOP;
 packet:=packet||E'
## Guidance sources
General guidance reviewed '||(spec->>'checked_on')||'. Recheck current program rules and all deadlines.'||src;
 INSERT INTO documents(project_id,pathway_id,kind,title,body,source_url,is_ai_generated)
 VALUES(target_project,path_id,'research_note',sample_prefix||(spec->>'name')||' working plan',packet,spec->'sources'->0->>'url',false);
 INSERT INTO communications(project_id,pathway_id,area,direction,channel,status,subject,body)
 VALUES(target_project,path_id,spec->>'area','outbound','email','draft',sample_prefix||(spec->>'name')||' inquiry',sample_prefix||E'DRAFT FOR HUMAN REVIEW. Not sent. Verify the recipient and every claim before use.

Hello [verified recipient],

'||(spec->>'inquiry')||E'

Our recorded project concept (unverified): '||p.business_thesis||E'

[Your name and organization]');
 RETURN jsonb_build_object('id',path_id,'created',true);
END $$;
REVOKE ALL ON FUNCTION create_pathway_plan(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION create_pathway_plan(uuid,text) TO authenticated;
CREATE FUNCTION start_pathway_workflow(target_pathway uuid, requested_action text, idempotency_key uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE uid text:=public.app_user_id(); p project_pathways%ROWTYPE; r workflow_runs%ROWTYPE;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
 IF requested_action NOT IN ('research','draft','review') OR idempotency_key IS NULL THEN RAISE EXCEPTION 'Invalid action'; END IF;
 SELECT * INTO p FROM project_pathways WHERE id=target_pathway AND user_id=uid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pathway not found'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(target_pathway::text||requested_action,0));
 SELECT * INTO r FROM workflow_runs WHERE user_id=uid AND request_key=idempotency_key;
 IF FOUND THEN
  IF r.pathway_id<>target_pathway OR r.action<>requested_action THEN RAISE EXCEPTION 'Request key belongs to a different action'; END IF;
  RETURN jsonb_build_object('id',r.id,'created',false);
 END IF;
 SELECT * INTO r FROM workflow_runs WHERE pathway_id=target_pathway AND action=requested_action AND status='running';
 IF FOUND THEN RETURN jsonb_build_object('id',r.id,'created',false); END IF;
 INSERT INTO workflow_runs(project_id,pathway_id,action,request_key) VALUES(p.project_id,p.id,requested_action,idempotency_key) RETURNING * INTO r;
 RETURN jsonb_build_object('id',r.id,'created',true);
END $$;
REVOKE ALL ON FUNCTION start_pathway_workflow(uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION start_pathway_workflow(uuid,text,uuid) TO authenticated;
